function [mvar,media] = montemedia(X,RF,RC,legame,valuta,vm,t,p,rendimento,dati,giorni,tipo,l,lambda,datidelta)%MONTEMEDIA	average of Monte Carlo VaR.%%	[mvar,media] = montemedia(X,RF,RC,legame,valuta,vm,t,p,rendimento,dati,giorni,tipo,l,lambda,datidelta) %   calculates the average of Monte Carlo VaR in the past days using n%   data.%	Lambda is the weight in EWMA volatility forecast.%   If Datidelta = 0 the mapping procedure is calculated over all X,%   = 1 only with defined data.%%	All data must be in columns.%%	See MONTEVAR%%	Copyright (c) 2004 by Flavio Bazzana%   Department of Computer and Management Sciences%   University of Trento%   38100 - Trento ITALY%   flavio.bazzana@economia.unitn.itn=size(X,1);m=length(valuta);[DX,DR,cambi,fattori,prezzi] = rendimenti(X,RF,RC,rendimento);[deltax,dev,cor,C] = semplicecorr(DX,DR,legame);for i=1:giornihome; disp(i)% VaR interval	X1=X(n-dati-i:n-i,:);	RF1=RF(n-dati-i:n-i,:);	RC1=RC(n-dati-i:n-i,:);	% calculation of montevar over such interval		[DX,DR,cambi,fattori,prezzi] = rendimenti(X1,RF1,RC1,rendimento);	if lambda==1		[delta,dev,cor,C] = semplicecorr(DX,DR,legame);		else [delta,dev,cor,C] = ewmacorr(DX,DR,legame,lambda);	end	if datidelta==1		[mvar(i)] = montevar(delta,C,legame,valuta,cambi,fattori,prezzi,vm,t,p,tipo,l,rendimento);		else [mvar(i)] = montevar(deltax,C,legame,valuta,cambi,fattori,prezzi,vm,t,p,tipo,l,rendimento);	endend% average calculationmedia=mean(mvar);